import type {
  DeckOptionPreset,
  DeckOptionsSettings,
  LeechAction,
  NewCardInsertionOrder,
  NewCardGatherOrder,
  NewCardSortOrder,
  NewReviewOrder,
  ReviewCardOrder,
  ReviewInterval,
} from "./types";
import { normalizeReviewInterval } from "./scheduler";

export const STANDARD_PRESET_ID = "standard";

export const DEFAULT_DECK_OPTION_PRESET: DeckOptionPreset = {
  id: STANDARD_PRESET_ID,
  name: "標準",
  learningSteps: [{ value: 1, unit: "minute" }, { value: 10, unit: "minute" }],
  relearningSteps: [{ value: 10, unit: "minute" }],
  graduatingIntervalDays: 1,
  easyIntervalDays: 4,
  newCardInsertionOrder: "sequential",
  newCardGatherOrder: "deck",
  newCardSortOrder: "cardType",
  newCardsIgnoreReviewLimit: false,
  newReviewOrder: "after",
  interdayLearningOrder: "before",
  reviewOrder: "due",
  buryNewSiblings: true,
  buryReviewSiblings: true,
  buryInterdayLearningSiblings: false,
  autoplayAudio: true,
  skipAnswerAudio: false,
  maximumAnswerSeconds: 60,
  leechThreshold: 8,
  leechAction: "tag",
  maximumIntervalDays: 36_500,
  startingEase: 2.5,
  easyBonus: 1.3,
  intervalModifier: 1,
  hardInterval: 1.2,
  newInterval: 0,
  minimumIntervalDays: 1,
};

const clamp = (value: unknown, fallback: number, minimum: number, maximum: number, decimals = 0): number => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  const factor = 10 ** decimals;
  return Math.min(maximum, Math.max(minimum, Math.round(numeric * factor) / factor));
};

function normalizeSteps(value: unknown, fallback: ReviewInterval[]): ReviewInterval[] {
  if (!Array.isArray(value)) return fallback.map((step) => ({ ...step }));
  return value.slice(0, 10).flatMap((step, index) => {
    if (!step || typeof step !== "object") return [];
    return [normalizeReviewInterval(step as Partial<ReviewInterval>, fallback[Math.min(index, fallback.length - 1)] ?? fallback[0])];
  });
}

export function normalizeDeckOptionPreset(value: Partial<DeckOptionPreset> | undefined, id = STANDARD_PRESET_ID): DeckOptionPreset {
  const fallback = DEFAULT_DECK_OPTION_PRESET;
  const insertion = value?.newCardInsertionOrder as NewCardInsertionOrder;
  const gather = value?.newCardGatherOrder as NewCardGatherOrder;
  const newSort = value?.newCardSortOrder as NewCardSortOrder;
  const newReview = value?.newReviewOrder as NewReviewOrder;
  const interday = value?.interdayLearningOrder as NewReviewOrder;
  const reviewOrder = value?.reviewOrder as ReviewCardOrder;
  const leechAction = value?.leechAction as LeechAction;
  const graduating = clamp(value?.graduatingIntervalDays, fallback.graduatingIntervalDays, 1, 36_500);
  return {
    id,
    name: String(value?.name || (id === STANDARD_PRESET_ID ? "標準" : "デッキ設定")).slice(0, 80),
    learningSteps: normalizeSteps(value?.learningSteps, fallback.learningSteps),
    relearningSteps: normalizeSteps(value?.relearningSteps, fallback.relearningSteps),
    graduatingIntervalDays: graduating,
    easyIntervalDays: Math.max(graduating, clamp(value?.easyIntervalDays, fallback.easyIntervalDays, 1, 36_500)),
    newCardInsertionOrder: insertion === "random" ? insertion : "sequential",
    newCardGatherOrder: ["deckReverse", "positionAsc", "positionDesc", "randomNotes", "randomCards"].includes(gather) ? gather : "deck",
    newCardSortOrder: ["gathered", "cardTypeRandom", "randomNotes", "randomCards"].includes(newSort) ? newSort : "cardType",
    newCardsIgnoreReviewLimit: value?.newCardsIgnoreReviewLimit === true,
    newReviewOrder: newReview === "before" || newReview === "mix" ? newReview : "after",
    interdayLearningOrder: interday === "after" || interday === "mix" ? interday : "before",
    reviewOrder: ["overdue", "random", "intervalAsc", "intervalDesc", "easeAsc", "easeDesc"].includes(reviewOrder) ? reviewOrder : "due",
    buryNewSiblings: value?.buryNewSiblings !== false,
    buryReviewSiblings: value?.buryReviewSiblings !== false,
    buryInterdayLearningSiblings: value?.buryInterdayLearningSiblings === true,
    autoplayAudio: value?.autoplayAudio !== false,
    skipAnswerAudio: value?.skipAnswerAudio === true,
    maximumAnswerSeconds: clamp(value?.maximumAnswerSeconds, fallback.maximumAnswerSeconds, 0, 86_400),
    leechThreshold: clamp(value?.leechThreshold, fallback.leechThreshold, 0, 9999),
    leechAction: leechAction === "suspend" ? leechAction : "tag",
    maximumIntervalDays: clamp(value?.maximumIntervalDays, fallback.maximumIntervalDays, 1, 36_500),
    startingEase: clamp(value?.startingEase, fallback.startingEase, 1.3, 5, 2),
    easyBonus: clamp(value?.easyBonus, fallback.easyBonus, 1, 5, 2),
    intervalModifier: clamp(value?.intervalModifier, fallback.intervalModifier, 0.1, 5, 2),
    hardInterval: clamp(value?.hardInterval, fallback.hardInterval, 1, 5, 2),
    newInterval: clamp(value?.newInterval, fallback.newInterval, 0, 1, 2),
    minimumIntervalDays: clamp(value?.minimumIntervalDays, fallback.minimumIntervalDays, 1, 365),
  };
}

export function normalizeDeckOptionsSettings(value: Partial<DeckOptionsSettings> | undefined): DeckOptionsSettings {
  const presets = Object.fromEntries(Object.entries(value?.presets ?? {}).map(([id, preset]) => (
    [id, normalizeDeckOptionPreset(preset, id)]
  )));
  if (!presets[STANDARD_PRESET_ID]) presets[STANDARD_PRESET_ID] = normalizeDeckOptionPreset(undefined);
  const validId = (id: unknown): id is string => typeof id === "string" && Boolean(presets[id]);
  const deckPresetIds = Object.fromEntries(Object.entries(value?.deckPresetIds ?? {}).filter(([, id]) => validId(id)));
  const subdeckPresetIds = Object.fromEntries(Object.entries(value?.subdeckPresetIds ?? {}).filter(([, id]) => validId(id)));
  return {
    presets,
    defaultPresetId: validId(value?.defaultPresetId) ? value.defaultPresetId : STANDARD_PRESET_ID,
    deckPresetIds,
    subdeckPresetIds,
  };
}

export function subdeckPresetKey(deckId: string, sourceDeckId: string): string {
  return `${encodeURIComponent(deckId)}/${encodeURIComponent(sourceDeckId)}`;
}

export function presetForDeck(settings: DeckOptionsSettings, deckId?: string, sourceDeckId?: string): DeckOptionPreset {
  const subdeckId = deckId && sourceDeckId ? settings.subdeckPresetIds[subdeckPresetKey(deckId, sourceDeckId)] : undefined;
  const presetId = subdeckId ?? (deckId ? settings.deckPresetIds[deckId] : undefined) ?? settings.defaultPresetId;
  return settings.presets[presetId] ?? settings.presets[STANDARD_PRESET_ID];
}

export function clonePreset(source: DeckOptionPreset, id: string, name: string): DeckOptionPreset {
  return normalizeDeckOptionPreset({
    ...source,
    name,
    learningSteps: source.learningSteps.map((step) => ({ ...step })),
    relearningSteps: source.relearningSteps.map((step) => ({ ...step })),
  }, id);
}

export function formatSteps(steps: readonly ReviewInterval[]): string {
  return steps.map((step) => `${step.value}${step.unit === "minute" ? "m" : step.unit === "hour" ? "h" : "d"}`).join(" ");
}

export function parseSteps(value: string): ReviewInterval[] | undefined {
  const trimmed = value.trim();
  if (!trimmed) return [];
  const output: ReviewInterval[] = [];
  for (const token of trimmed.split(/\s+/)) {
    const match = token.toLowerCase().match(/^(\d+)(m|h|d)$/);
    if (!match) return undefined;
    output.push({
      value: Number(match[1]),
      unit: match[2] === "m" ? "minute" : match[2] === "h" ? "hour" : "day",
    });
  }
  return output;
}
