import type { BackupSnapshot } from "./types";

export const BACKUP_FORMAT_VERSION = 1;
export const MAX_INTERNAL_BACKUPS = 20;
export const AUTOMATIC_BACKUP_INTERVAL_MS = 30 * 60 * 1000;

export function backupDeckIds(snapshot: BackupSnapshot): Set<string> {
  return new Set(snapshot.deckStates.map((state) => state.id));
}

export function shouldRemoveReviewAfterBackup(
  snapshot: BackupSnapshot,
  deckId: string,
  reviewId: IDBValidKey,
): boolean {
  return backupDeckIds(snapshot).has(deckId)
    && typeof reviewId === "number"
    && reviewId > (snapshot.lastReviewId ?? 0);
}

function checksumContent(snapshot: Omit<BackupSnapshot, "checksum"> | BackupSnapshot): string {
  const { id: _id, createdAt: _createdAt, reason: _reason, checksum: _checksum, ...content } = snapshot as BackupSnapshot;
  return JSON.stringify(content);
}

export async function calculateBackupChecksum(snapshot: Omit<BackupSnapshot, "checksum"> | BackupSnapshot): Promise<string> {
  const bytes = new TextEncoder().encode(checksumContent(snapshot));
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map((value) => value.toString(16).padStart(2, "0")).join("");
}

export function isBackupSnapshot(value: unknown): value is BackupSnapshot {
  if (!value || typeof value !== "object") return false;
  const record = value as Partial<BackupSnapshot>;
  return record.appId === "apkg-simulator"
    && record.formatVersion === BACKUP_FORMAT_VERSION
    && typeof record.id === "string"
    && Number.isFinite(record.createdAt)
    && typeof record.appVersion === "string"
    && (record.reason === "automatic" || record.reason === "background" || record.reason === "manual")
    && typeof record.checksum === "string"
    && Boolean(record.settings && typeof record.settings === "object" && record.settings.key === "app")
    && Array.isArray(record.deckStates)
    && Array.isArray(record.progress)
    && Array.isArray(record.sessions)
    && Array.isArray(record.reviewFlags)
    && Array.isArray(record.dailyNew)
    && Array.isArray(record.dailyReview)
    && Array.isArray(record.todayOnlyLimits)
    && (record.reviews === undefined || Array.isArray(record.reviews));
}

function hasValidBackupRecords(snapshot: BackupSnapshot): boolean {
  const deckIds = new Set<string>();
  for (const state of snapshot.deckStates) {
    if (!state || typeof state.id !== "string" || deckIds.has(state.id)) return false;
    if (!Number.isFinite(state.reviewCount) || state.reviewCount < 0) return false;
    if (!Number.isFinite(state.correctCount) || state.correctCount < 0) return false;
    deckIds.add(state.id);
  }
  const belongsToKnownDeck = (value: unknown): boolean => {
    if (!value || typeof value !== "object") return false;
    const deckId = (value as { deckId?: unknown }).deckId;
    return typeof deckId === "string" && deckIds.has(deckId);
  };
  const recordGroups: unknown[][] = [
    snapshot.progress,
    snapshot.sessions,
    snapshot.reviewFlags,
    snapshot.dailyNew,
    snapshot.dailyReview,
    snapshot.todayOnlyLimits,
    snapshot.reviews ?? [],
  ];
  if (!recordGroups.every((records) => records.every(belongsToKnownDeck))) return false;
  return snapshot.lastReviewId === undefined
    || (Number.isInteger(snapshot.lastReviewId) && snapshot.lastReviewId >= 0);
}

export async function verifyBackupSnapshot(value: unknown): Promise<BackupSnapshot> {
  if (!isBackupSnapshot(value)) throw new Error("APKG Simulatorのバックアップファイルではありません。");
  const checksum = await calculateBackupChecksum(value);
  if (checksum !== value.checksum) throw new Error("バックアップが破損しているため復元できません。");
  if (!hasValidBackupRecords(value)) throw new Error("バックアップ内の学習データが正しくありません。");
  return value;
}

export function backupFileName(createdAt: number): string {
  const date = new Date(createdAt);
  const part = (value: number): string => String(value).padStart(2, "0");
  return `APKG-Simulator-backup-${date.getFullYear()}${part(date.getMonth() + 1)}${part(date.getDate())}-${part(date.getHours())}${part(date.getMinutes())}.apkgbackup.json`;
}
