import type {
  Grade,
  ProgressRecord,
  ReviewInterval,
  ReviewIntervals,
  ReviewIntervalUnit,
  ReviewScheduleSettings,
} from "./types";

const MINUTE_MS = 60 * 1000;
const HOUR_MS = 60 * MINUTE_MS;

export const DEFAULT_DAY_START_MINUTES = 4 * 60;
export const DEFAULT_LOOKAHEAD_MINUTES = 0;

export const INTERVAL_UNIT_LIMITS: Record<ReviewIntervalUnit, number> = {
  minute: 180,
  hour: 72,
  day: 365,
};

export const DEFAULT_REVIEW_INTERVALS: ReviewIntervals = {
  again: { value: 30, unit: "minute" },
  hard: { value: 6, unit: "hour" },
  good: { value: 1, unit: "day" },
  easy: { value: 3, unit: "day" },
};

export const REVIEW_PRESETS = {
  standard: DEFAULT_REVIEW_INTERVALS,
  week: {
    again: { value: 15, unit: "minute" },
    hard: { value: 3, unit: "hour" },
    good: { value: 1, unit: "day" },
    easy: { value: 3, unit: "day" },
  },
  threeDays: {
    again: { value: 10, unit: "minute" },
    hard: { value: 1, unit: "hour" },
    good: { value: 6, unit: "hour" },
    easy: { value: 1, unit: "day" },
  },
} satisfies Record<string, ReviewIntervals>;

export type ReviewPresetName = keyof typeof REVIEW_PRESETS | "custom";

function isReviewIntervalUnit(value: unknown): value is ReviewIntervalUnit {
  return value === "minute" || value === "hour" || value === "day";
}

export function normalizeReviewInterval(
  interval: Partial<ReviewInterval> | undefined,
  fallback: ReviewInterval,
): ReviewInterval {
  const unit = isReviewIntervalUnit(interval?.unit) ? interval.unit : fallback.unit;
  const numericValue = Number(interval?.value);
  const value = Number.isFinite(numericValue) ? Math.round(numericValue) : fallback.value;
  const normalizedValue = Math.min(INTERVAL_UNIT_LIMITS[unit], Math.max(1, value));
  // v1.2までの「24時間」は、日付更新時刻を基準にする「1日」へ移行する。
  if (unit === "hour" && normalizedValue === 24) return { value: 1, unit: "day" };
  return { value: normalizedValue, unit };
}

export function cloneReviewIntervals(intervals: ReviewIntervals): ReviewIntervals {
  return {
    again: { ...intervals.again },
    hard: { ...intervals.hard },
    good: { ...intervals.good },
    easy: { ...intervals.easy },
  };
}

export function normalizeReviewIntervals(intervals: Partial<ReviewIntervals> | undefined): ReviewIntervals {
  return {
    again: normalizeReviewInterval(intervals?.again, DEFAULT_REVIEW_INTERVALS.again),
    hard: normalizeReviewInterval(intervals?.hard, DEFAULT_REVIEW_INTERVALS.hard),
    good: normalizeReviewInterval(intervals?.good, DEFAULT_REVIEW_INTERVALS.good),
    easy: normalizeReviewInterval(intervals?.easy, DEFAULT_REVIEW_INTERVALS.easy),
  };
}

export function normalizeReviewSchedule(
  schedule: Partial<ReviewScheduleSettings> | undefined,
): ReviewScheduleSettings {
  const dayStart = Number(schedule?.dayStartMinutes);
  const lookahead = Number(schedule?.lookaheadMinutes);
  const deckOverrides = Object.fromEntries(Object.entries(schedule?.deckOverrides ?? {}).map(
    ([deckId, intervals]) => [deckId, normalizeReviewIntervals(intervals)],
  ));
  return {
    intervals: normalizeReviewIntervals(schedule?.intervals),
    dayStartMinutes: Number.isFinite(dayStart)
      ? Math.min(1439, Math.max(0, Math.round(dayStart)))
      : DEFAULT_DAY_START_MINUTES,
    lookaheadMinutes: Number.isFinite(lookahead)
      ? Math.min(180, Math.max(0, Math.round(lookahead)))
      : DEFAULT_LOOKAHEAD_MINUTES,
    deckOverrides,
  };
}

export function reviewPresetFor(intervals: ReviewIntervals): ReviewPresetName {
  for (const [name, preset] of Object.entries(REVIEW_PRESETS) as [keyof typeof REVIEW_PRESETS, ReviewIntervals][]) {
    if ((Object.keys(preset) as Grade[]).every((grade) => (
      preset[grade].value === intervals[grade].value && preset[grade].unit === intervals[grade].unit
    ))) return name;
  }
  return "custom";
}

export function formatReviewInterval(interval: ReviewInterval, suffix = "後"): string {
  const unit = interval.unit === "minute" ? "分" : interval.unit === "hour" ? "時間" : "日";
  return `${interval.value}${unit}${suffix}`;
}

export function studyDayStartAt(now: number, dayStartMinutes: number): number {
  const date = new Date(now);
  const hours = Math.floor(dayStartMinutes / 60);
  const minutes = dayStartMinutes % 60;
  const start = new Date(date.getFullYear(), date.getMonth(), date.getDate(), hours, minutes, 0, 0);
  if (start.getTime() > now) start.setDate(start.getDate() - 1);
  return start.getTime();
}

export function nextStudyDayStart(now: number, dayStartMinutes: number): number {
  const next = new Date(studyDayStartAt(now, dayStartMinutes));
  next.setDate(next.getDate() + 1);
  return next.getTime();
}

export function dueAtForInterval(
  interval: ReviewInterval,
  reviewedAt: number,
  dayStartMinutes = DEFAULT_DAY_START_MINUTES,
): number {
  if (interval.unit === "minute") return reviewedAt + interval.value * MINUTE_MS;
  if (interval.unit === "hour") return reviewedAt + interval.value * HOUR_MS;
  const due = new Date(studyDayStartAt(reviewedAt, dayStartMinutes));
  due.setDate(due.getDate() + interval.value);
  return due.getTime();
}

export function dueAtForGrade(
  grade: Grade,
  reviewedAt: number,
  intervals: ReviewIntervals = DEFAULT_REVIEW_INTERVALS,
  dayStartMinutes = DEFAULT_DAY_START_MINUTES,
): number {
  return dueAtForInterval(intervals[grade], reviewedAt, dayStartMinutes);
}

export function progressDueAt(progress: ProgressRecord): number {
  return progress.dueAt ?? dueAtForGrade(progress.lastGrade, progress.lastReviewedAt);
}
