export const MIN_ANSWER_SCALE = 0.5;
export const MAX_ANSWER_SCALE = 2;
export const ANSWER_SCALE_STEP = 0.1;
export const DEFAULT_ANSWER_SCALE = 1;

export function clampAnswerScale(value: number): number {
  if (!Number.isFinite(value)) return DEFAULT_ANSWER_SCALE;
  const clamped = Math.min(MAX_ANSWER_SCALE, Math.max(MIN_ANSWER_SCALE, value));
  return Math.round(clamped / ANSWER_SCALE_STEP) * ANSWER_SCALE_STEP;
}

export function scaledMediaWidth(baseWidth: number, scale: number): number {
  if (!Number.isFinite(baseWidth) || baseWidth <= 0) return 0;
  return baseWidth * clampAnswerScale(scale);
}
